<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Connect a mobile device · CareSys</title><link rel="stylesheet" href="/assets/caresys.css"><link rel="stylesheet" href="/assets/mobile-pairing.css"></head>
<body><main class="pairing-shell"><a class="brand" href="/app"><span class="brand-mark" aria-hidden="true">✚</span>CareSys</a>
<section class="pairing-card" aria-labelledby="pairing-heading"><span class="badge">MOBILE ACCESS</span><h1 id="pairing-heading">Connect your mobile device</h1><p>Keep your care workspace close. Open pairing in the mobile app, then enter the code shown on that device.</p>
<?php if($error): ?><div class="alert error" role="alert"><?= esc($error) ?></div><?php endif ?>
<?php if($success): ?><div class="alert" role="status"><?= esc($success) ?></div><?php endif ?>
<?php if($device): ?>
<div class="pairing-device"><span class="sub">DEVICE REQUESTING ACCESS</span><h2><?= esc($device['device_name']) ?></h2><p>Code <strong><?= esc($code) ?></strong></p></div>
<p>Approve only if you started pairing on this device. Access uses your current account and agency permissions and expires after 15 minutes.</p>
<form method="post" action="/mobile-enrollment/approve"><?= csrf_field() ?><input type="hidden" name="user_code" value="<?= esc($code,'attr') ?>"><div class="field"><label for="pair-password">Confirm your password</label><input id="pair-password" name="password" type="password" autocomplete="current-password" maxlength="255" required></div><div class="field"><label><input type="checkbox" name="confirm" value="yes" required> I recognize this device and its pairing code.</label></div><button type="submit">Approve this device</button><a class="pairing-cancel" href="/mobile-enrollment">Cancel</a></form>
<?php elseif(!$success): ?>
<form method="post" action="/mobile-enrollment/review"><?= csrf_field() ?><div class="field"><label for="user-code">Pairing code from your device</label><input id="user-code" name="user_code" placeholder="Enter your device code" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="16" required aria-describedby="code-help"><small id="code-help">Use the actual 12-character code generated by your device. It expires after 5 minutes.</small></div><button type="submit">Review device</button></form>
<?php else: ?><p>The mobile app can now finish connecting. You can close this page.</p><a href="/mobile-enrollment">Connect another device</a><?php endif ?>
<a class="pairing-back" href="/app">← Back to your workspace</a></section>
<?php if($testDeviceUrl): ?><section class="pairing-card" aria-labelledby="local-testing-heading"><span class="badge">LOCAL DEVELOPMENT</span><h2 id="local-testing-heading">No mobile app connected yet?</h2><p>Open the local test device to generate a real pairing code. Keep its tab open, then return here to review and approve that code.</p><a href="<?= esc($testDeviceUrl,'attr') ?>" target="_blank" rel="noopener noreferrer">Open local test device ↗</a></section><?php endif ?>
<section class="pairing-card" aria-labelledby="devices-heading"><h2 id="devices-heading">Connected devices</h2><p class="sub">Revoking access signs that device out immediately.</p>
<?php if(!$devices): ?><p>No active mobile connections.</p><?php endif ?>
<?php foreach($devices as $entry): ?><div class="pairing-session"><div><strong><?= esc(substr($entry->name,7)) ?></strong><br><small>Expires <?= esc((string)$entry->expires) ?> UTC</small></div><form method="post" action="/mobile-enrollment/revoke"><?= csrf_field() ?><input type="hidden" name="token_id" value="<?= (int)$entry->id ?>"><button class="secondary" type="submit">Revoke access</button></form></div><?php endforeach ?>
</section><p class="pairing-footnote">Never share a pairing code or approve a request from someone else.</p></main></body></html>
